// External art authoring only. Existing object transforms, colliders and gameplay are preserved.
using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1DetailApply {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/",P="Assets/Afrer_Seconds/05.Model/Props/1F/";
 static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");static string Out=>Root+"/Docs/Review/2026-11-13_1F_DetailPass/";
 static Dictionary<string,Material> mats;static List<object> instances=new List<object>();
 public static object Refine(){Check();instances.Clear();mats=Directory.GetFiles(E+"Materials","AE_M_*.mat").Select(p=>AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'))).Where(m=>m).ToDictionary(m=>m.name);
 foreach(var m in mats.Values.Where(m=>m.name.StartsWith("AE_M_Ivy"))){if(m.name!="AE_M_IvyBark")m.SetFloat("_Cull",0);m.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(E+"Textures/AE_Grain_Normal.png"));m.SetFloat("_BumpScale",.10f);m.SetTextureScale("_BaseMap",Vector2.one*6);m.EnableKeyword("_NORMALMAP");EditorUtility.SetDirty(m);}
 var qs=new List<JToken>();foreach(string file in new[]{"props","lift","walls"})qs.AddRange(JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_DetailPass/"+file+".json")));qs.Add(JObject.Parse(File.ReadAllText(Root+"/SourceAssets/F1_DetailPass/ivy.json")));
 foreach(var q in qs){string n=(string)q["name"],folder=n=="AE_WallIvy"||n.EndsWith("_WallTrim")?E:P;var proto=Import(q,folder);var source=proto.GetComponentsInChildren<MeshFilter>().ToDictionary(f=>f.name);foreach(var f in SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>source.ContainsKey(f.name))){var src=source[f.name];f.sharedMesh=src.sharedMesh;f.GetComponent<Renderer>().sharedMaterials=src.GetComponent<Renderer>().sharedMaterials;if(PrefabUtility.IsPartOfPrefabInstance(f)){PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());}}}
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(SceneManager.GetActiveScene());EditorSceneManager.SaveScene(SceneManager.GetActiveScene());return new{refined=qs.Count,saved=true};}
 static void Check(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F edit required");}
 static GameObject Import(JToken q,string folder){string name=(string)q["name"],path=folder+name+".fbx";string old=AssetDatabase.AssetPathToGUID(path);File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_DetailPass_20261113/candidate/"+name+".fbx"),path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var im=(ModelImporter)AssetImporter.GetAtPath(path);im.isReadable=false;im.importAnimation=false;im.importCameras=false;im.importLights=false;foreach(string n in q["materials"].Values<string>())im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),n),mats[n]);im.SaveAndReimport();if(!string.IsNullOrEmpty(old)&&old!=AssetDatabase.AssetPathToGUID(path))throw new Exception("GUID changed "+name);return AssetDatabase.LoadAssetAtPath<GameObject>(path);}
 static void Attach(GameObject proto,Transform parent,bool integrate=false,bool dynamic=false){string name=proto.name;var old=parent.Find(name);if(old)throw new Exception("Already attached "+parent.name+"/"+name);var go=(GameObject)PrefabUtility.InstantiatePrefab(proto,parent);go.name=name;go.transform.localPosition=Vector3.zero;go.transform.localRotation=Quaternion.identity;go.transform.localScale=Vector3.one;
 var rs=go.GetComponentsInChildren<Renderer>();foreach(var t in go.GetComponentsInChildren<Transform>()){GameObjectUtility.SetStaticEditorFlags(t.gameObject,dynamic?0:StaticEditorFlags.BatchingStatic);}
 foreach(var r in rs){r.motionVectorGenerationMode=dynamic?MotionVectorGenerationMode.Object:MotionVectorGenerationMode.Camera;}
 var own=go.GetComponent<LODGroup>();var baseGroup=integrate?parent.GetComponent<LODGroup>():null;
 if(baseGroup){if(own)UnityEngine.Object.DestroyImmediate(own);var lod=baseGroup.GetLODs();for(int i=0;i<lod.Length;i++)lod[i].renderers=lod[i].renderers.Concat(rs.Where(r=>r.name.EndsWith("LOD"+Math.Min(i,2)))).ToArray();baseGroup.SetLODs(lod);baseGroup.RecalculateBounds();}
 else{if(!own)own=go.AddComponent<LODGroup>();own.SetLODs(new[]{new LOD(.14f,rs.Where(r=>r.name.EndsWith("LOD0")).ToArray()),new LOD(.055f,rs.Where(r=>r.name.EndsWith("LOD1")).ToArray()),new LOD(.015f,rs.Where(r=>r.name.EndsWith("LOD2")).ToArray())});own.RecalculateBounds();}
 instances.Add(new{asset=AssetDatabase.GetAssetPath(proto),parent=AnimationUtility.CalculateTransformPath(parent,null),name,integratedLOD=baseGroup!=null,dynamic});}
 public static object Run(){Check();instances.Clear();
 void Mat(string n,Color color,float smooth){string p=E+"Materials/AE_M_"+n+".mat";var m=AssetDatabase.LoadAssetAtPath<Material>(p);if(!m){m=new Material(Shader.Find("Universal Render Pipeline/Lit")){name="AE_M_"+n};AssetDatabase.CreateAsset(m,p);}m.SetColor("_BaseColor",color);m.SetFloat("_Metallic",0);m.SetFloat("_Smoothness",smooth);EditorUtility.SetDirty(m);}
 Mat("IvyDark",new Color(.17f,.23f,.105f),.23f);Mat("IvyMid",new Color(.24f,.31f,.13f),.28f);Mat("IvyLight",new Color(.31f,.37f,.16f),.25f);Mat("IvyDry",new Color(.35f,.27f,.13f),.13f);Mat("IvyVein",new Color(.36f,.40f,.20f),.2f);Mat("IvyBark",new Color(.23f,.18f,.10f),.14f);
 mats=Directory.GetFiles(E+"Materials","AE_M_*.mat").Select(p=>AssetDatabase.LoadAssetAtPath<Material>(p.Replace('\\','/'))).Where(m=>m).ToDictionary(m=>m.name);
 var scene=SceneManager.GetActiveScene();var ts=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();
 foreach(var q in JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_DetailPass/props.json"))){string n=(string)q["name"],kind=n.Substring(3);var proto=Import(q,P);var targets=ts.Where(t=>t.gameObject.activeInHierarchy&&t.name.StartsWith("F1_")&&t.parent&&t.parent.name.StartsWith("1F_")&&(kind=="Desk"?t.name.Contains("Desk_")&&!t.name.EndsWith("_Chair"):kind=="OfficeChair"?t.name.EndsWith("_Chair"):t.name.Contains("_"+kind+"_"))).ToArray();foreach(var t in targets)Attach(proto,t,true);}
 var lift=GameObject.Find("F1_VL_LiftAssembly").transform;
 foreach(var q in JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_DetailPass/lift.json"))){var proto=Import(q,P);string parent=(string)q["parent"];Attach(proto,lift.Find(parent),false,!parent.StartsWith("FixedShaft"));if(parent.StartsWith("Car/Door")){string side=parent.Substring(8);foreach(string other in new[]{"FixedShaft/LandingDoor"+side,"FixedShaft/Landing_B1/LandingDoor"+side})Attach(proto,lift.Find(other),false,true);}}
 foreach(var q in JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_DetailPass/walls.json"))){string n=(string)q["name"],room=n.Split('_')[1];var proto=Import(q,E);Attach(proto,GameObject.Find("AE_"+room+"_Walls").transform);}
 var iq=JObject.Parse(File.ReadAllText(Root+"/SourceAssets/F1_DetailPass/ivy.json"));var ivyProto=Import(iq,E);var ivy=GameObject.Find("AE_WallIvy");var source=ivyProto.GetComponentsInChildren<MeshFilter>();foreach(var f in ivy.GetComponentsInChildren<MeshFilter>(true)){var src=source.Single(s=>s.name==f.name);f.sharedMesh=src.sharedMesh;f.GetComponent<Renderer>().sharedMaterials=src.GetComponent<Renderer>().sharedMaterials;if(PrefabUtility.IsPartOfPrefabInstance(f)){PrefabUtility.RecordPrefabInstancePropertyModifications(f);PrefabUtility.RecordPrefabInstancePropertyModifications(f.GetComponent<Renderer>());}}
 File.Copy(Root+"/SourceAssets/F1_DetailPass/AEWeathering.hlsl",E+"AEWeathering.hlsl",true);AssetDatabase.ImportAsset(E+"AEWeathering.hlsl",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);
 AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(Out+"apply.json",JsonConvert.SerializeObject(instances,Formatting.Indented));return new{detailInstances=instances.Count,ivyReplaced=true,saved=true};}
}
